// 全局变量，根据系统时钟计算
u16 fac_us = 72;  // 假设系统时钟72MHz，1us需要72个计数
u16 fac_ms = 72000; // 1ms需要72000个计数

void delay_us(u16 nus) {
    SysTick->LOAD = nus * fac_us;
    SysTick->VAL = 0;
    SysTick->CTRL = 0x01; // 使能，不挂中断
    while (!(SysTick->CTRL & (1 << 16))); // 等待计数到0
    SysTick->CTRL = 0; // 关闭
}

void delay_ms(u16 nms) {
    while (nms--) {
        delay_us(1000);
    }
}
```

