    if (i2c == NULL) return I2C_ERROR_TIMEOUT;

    i2c->config.sda_write(false);
    i2c->config.scl_write(true);
    i2c->config.delay_us(i2c->half_period_us);

    i2c->config.sda_write(true);
    i2c->config.delay_us(i2c->half_period_us);

    return I2C_OK;
}

